// Valida lo que manda el panel (lib/usuarios/avisoRol.ts): { evento: 'usuario_rol', aviso_id }.
// Solo eso: destinatario y textos se leen de la MySQL en el nodo siguiente (el webhook es publico).
const body = $json.body || {};
const id = parseInt(body.aviso_id, 10);
if (body.evento !== 'usuario_rol' || !(id > 0)) return null;
return { json: { id } };

// Arma el correo de bienvenida con la fila de "Leer aviso" (usuarios_avisos_rol + users_config).
// Ningún texto ni dirección viene del webhook (es público): todo lo guardó el panel
// (lib/usuarios/avisoRol.ts). Sin fila = ya se mandó, tiene más de un día o la persona ya no tiene ese rol.
//
// Diseño sobrio y sin imágenes: el nombre de la marca va como texto (Outlook y Gmail bloquean las
// imágenes externas de remitentes nuevos), sin degradados ni texto oculto, un solo enlace cuyo texto
// es la misma dirección a la que lleva, y versión en texto plano: todo eso baja la nota de spam.
const a = $json;
if (!a || !a.id) return null;
const esCorreo = (v) => /^[^\s@<>,;()]+@[^\s@<>,;()]+\.[^\s@<>,;()]+$/.test(String(v || '').trim());
const para = String(a.email || '').trim().toLowerCase();
if (!esCorreo(para)) return null;

let grupos = [];
try { grupos = JSON.parse(a.secciones_json || '[]'); } catch (e) { grupos = []; }
if (!Array.isArray(grupos)) grupos = [];

// Valencia es OSC; Caracas, Panamá y sin sede, SUPRICOM.
const SEDES = { 9: 'Valencia', 10: 'Caracas', 7: 'Panamá' };
const sede = SEDES[Number(a.cids)] || '';
const M = Number(a.cids) === 9
  ? { marca: 'OSC', razon: 'Office Solutions Center 2004, C.A.', color: '#1746C1' }
  : { marca: 'SUPRICOM', razon: Number(a.cids) === 10 ? 'SUPRICOM CCS 21, C.A.' : Number(a.cids) === 7 ? 'SUPRICOM, S.A.' : 'SUPRICOM', color: '#0E7FD1' };
const TINTA = '#0F172A';
const GRIS = '#64748B';
const LINEA = '#E5E7EB';
const F = "font-family:-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
// Un correo escrito como texto no se vuelve enlace en Outlook/Gmail si se corta con un span vacío.
const sinEnlace = (v) => esc(v).replace('@', '<span>@</span>').replace(/\./g, '<span>.</span>');

const url = /^https?:\/\//.test(String(a.url_panel || '')) ? String(a.url_panel).replace(/\/+$/, '') : 'https://panel.supricom.com.ve';
const dominio = url.replace(/^https?:\/\//, '');
const rol = a.rol_nombre || a.rol;
const nombre = String(a.nombre || '').trim().split(/\s+/)[0] || '';
const cambio = !!a.rol_anterior;
const asunto = cambio ? 'Tu rol en el Panel SUPRICOM ahora es ' + rol : 'Bienvenido al Panel SUPRICOM: rol ' + rol;
const titulo = cambio ? 'Tu rol cambió' : 'Ya tienes acceso al panel';
const bajada = cambio
  ? 'Pasaste de ' + esc(a.rol_anterior) + ' a <strong style="color:' + TINTA + '">' + esc(rol) + '</strong>.'
  : 'Se te asignó el rol <strong style="color:' + TINTA + '">' + esc(rol) + '</strong>' + (sede ? ' en ' + esc(sede) : '') + '.';

const dato = (etiqueta, valor, ultimo) =>
  '<tr><td style="padding:14px 0;' + (ultimo ? '' : 'border-bottom:1px solid ' + LINEA + ';') + F + ';font-size:13px;color:' + GRIS + ';width:120px;vertical-align:top">' + etiqueta + '</td>' +
  '<td style="padding:14px 0;' + (ultimo ? '' : 'border-bottom:1px solid ' + LINEA + ';') + F + ';font-size:14px;color:' + TINTA + ';vertical-align:top">' + valor + '</td></tr>';

const datos = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-top:1px solid ' + LINEA + ';border-bottom:1px solid ' + LINEA + '">' +
  dato('Panel', '<a href="' + esc(url) + '" style="color:' + M.color + ';text-decoration:none;font-weight:600">' + esc(dominio) + '</a>') +
  dato('Rol', esc(rol) + (sede ? ' <span style="color:' + GRIS + '">· ' + esc(sede) + '</span>' : '')) +
  dato('Usuario', sinEnlace(para)) +
  dato('Clave', 'La misma que usas en Odoo', true) + '</table>';

const nota = '<p style="margin:20px 0 0 0;' + F + ';font-size:14px;line-height:1.6;color:' + GRIS + '">' +
  'Inicia sesión con tu usuario y tu contraseña de Odoo. El panel no tiene una clave propia: si la olvidas o quieres cambiarla, se hace en Odoo.' +
  (cambio ? ' Si tenías el panel abierto, vuelve a entrar para ver tu nuevo menú.' : '') + '</p>';

const boton = '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:28px 0 0 0"><tr>' +
  '<td bgcolor="' + TINTA + '" style="border-radius:8px;background:' + TINTA + '">' +
  '<a href="' + esc(url) + '" style="display:inline-block;padding:12px 22px;' + F + ';font-size:14px;font-weight:600;color:#FFFFFF;text-decoration:none;border-radius:8px">Abrir ' + esc(dominio) + '</a>' +
  '</td></tr></table>';

const lista = grupos.map((g) =>
  '<tr><td style="padding:22px 0 6px 0;' + F + ';font-size:11px;font-weight:600;letter-spacing:1.2px;text-transform:uppercase;color:' + GRIS + '">' + esc(g.area) + '</td></tr>' +
  (Array.isArray(g.secciones) ? g.secciones : []).map((s) =>
    '<tr><td style="padding:5px 0;' + F + ';font-size:14px;line-height:1.5;color:' + GRIS + '"><span style="color:' + TINTA + ';font-weight:600">' + esc(s.nombre) + '</span> &mdash; ' + esc(s.detalle) + '</td></tr>').join('')
).join('');

const queHace = '<h2 style="margin:40px 0 0 0;' + F + ';font-size:16px;font-weight:600;color:' + TINTA + '">Qué puedes hacer</h2>' +
  '<p style="margin:8px 0 0 0;' + F + ';font-size:14px;line-height:1.6;color:' + TINTA + '">' + esc(a.resumen) + '</p>' +
  (lista ? '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">' + lista + '</table>' : '');

const html = '<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light only"><title>' + esc(asunto) + '</title>' +
  '<style>@media (max-width:600px){.caja{padding:32px 22px!important}}</style></head>' +
  '<body style="margin:0;padding:0;background:#F6F7F9">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#F6F7F9" style="background:#F6F7F9"><tr><td align="center" style="padding:32px 12px">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px">' +
  // Marca como texto
  '<tr><td style="padding:0 4px 18px 4px;' + F + ';font-size:13px;font-weight:700;letter-spacing:3px;color:' + TINTA + '">' + M.marca +
  '<span style="color:' + M.color + '">.</span><span style="font-weight:400;letter-spacing:0;color:' + GRIS + '">&nbsp;&nbsp;Panel</span></td></tr>' +
  '<tr><td class="caja" bgcolor="#FFFFFF" style="background:#FFFFFF;border:1px solid ' + LINEA + ';border-radius:12px;padding:44px 40px">' +
  '<div style="width:32px;height:3px;background:' + M.color + ';border-radius:2px;line-height:3px;font-size:0">&nbsp;</div>' +
  '<h1 style="margin:22px 0 0 0;' + F + ';font-size:24px;line-height:1.3;font-weight:700;color:' + TINTA + '">' + titulo + '</h1>' +
  '<p style="margin:10px 0 0 0;' + F + ';font-size:15px;line-height:1.6;color:' + GRIS + '">Hola' + (nombre ? ' ' + esc(nombre) : '') + '. ' + bajada + '</p>' +
  '<div style="height:28px;line-height:28px;font-size:0">&nbsp;</div>' + datos + nota + boton + queHace +
  '</td></tr>' +
  '<tr><td style="padding:20px 4px 0 4px;' + F + ';font-size:12px;line-height:1.6;color:#94A3B8">' + esc(M.razon) + (sede ? ' · ' + esc(sede) : '') +
  '<br>Recibes este correo porque se te asignó un rol en el panel' + (a.asignado_por ? ' (' + sinEnlace(a.asignado_por) + ')' : '') + '. Si no lo esperabas, avísale a tu supervisor.</td></tr>' +
  '</table></td></tr></table></body></html>';

// Versión en texto plano (va como parte alterna del correo).
const texto = [
  (nombre ? 'Hola ' + nombre + '.' : 'Hola.'),
  '',
  cambio ? 'Tu rol en el Panel SUPRICOM cambió de ' + a.rol_anterior + ' a ' + rol + '.' : 'Ya tienes acceso al Panel SUPRICOM con el rol ' + rol + (sede ? ' en ' + sede : '') + '.',
  '',
  'Panel: ' + url,
  'Usuario: ' + para,
  'Clave: la misma que usas en Odoo',
  '',
  'Inicia sesión con tu usuario y tu contraseña de Odoo. El panel no tiene una clave propia: si la olvidas o quieres cambiarla, se hace en Odoo.',
  '',
  'Qué puedes hacer: ' + (a.resumen || ''),
  ...grupos.flatMap((g) => ['', String(g.area || '').toUpperCase(), ...(Array.isArray(g.secciones) ? g.secciones : []).map((s) => '- ' + s.nombre + ': ' + s.detalle)]),
  '',
  '--',
  M.razon + (sede ? ' · ' + sede : ''),
].join('\n');

// Mensaje MIME completo (multipart/alternative: texto + HTML) para la API de Gmail. El nodo Gmail de
// n8n solo manda HTML; un correo sin parte de texto suma puntos de spam.
const b64 = (s) => Buffer.from(s, 'utf8').toString('base64');
const partir = (s) => s.replace(/.{1,76}/g, (l) => l + '\r\n');
const asuntoCorto = asunto.slice(0, 200);
const limite = 'panel-' + a.id + '-' + Date.now().toString(36);
const mime = [
  'From: =?UTF-8?B?' + b64('Panel SUPRICOM') + '?= <dmedina@supricom.com.ve>',
  'To: ' + para,
  'Subject: =?UTF-8?B?' + b64(asuntoCorto) + '?=',
  'MIME-Version: 1.0',
  'Content-Type: multipart/alternative; boundary="' + limite + '"',
  '',
  '--' + limite,
  'Content-Type: text/plain; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  partir(b64(texto)),
  '--' + limite,
  'Content-Type: text/html; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  partir(b64(html)),
  '--' + limite + '--',
  '',
].join('\r\n');
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

return { json: { aviso_id: Number(a.id), para, asunto: asuntoCorto, raw } };
